const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "mysql",
  "inlineSchema": "generator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../lib/generated/prisma\"\n  binaryTargets = [\"native\", \"debian-openssl-1.0.x\", \"rhel-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ════════════════════════════════════════════════════════════\n//  ENUMS\n// ════════════════════════════════════════════════════════════\n\nenum OrderStatus {\n  PENDING // created, awaiting payment\n  PAID\n  PROCESSING // picking / packing\n  SHIPPED\n  DELIVERED\n  CANCELLED\n  REFUNDED\n}\n\nenum SaleType {\n  SQM\n  CONTAINER\n}\n\nenum PaymentStatus {\n  PENDING\n  AUTHORIZED\n  PAID\n  FAILED\n  REFUNDED\n  PARTIALLY_REFUNDED\n}\n\nenum PaymentMethod {\n  MTN_MOMO\n  AIRTEL_MONEY\n  CARD\n  BANK_TRANSFER\n  CASH_ON_DELIVERY\n}\n\nenum FulfillmentMethod {\n  DELIVERY\n  PICKUP\n}\n\nenum StockMovementType {\n  PURCHASE // stock received from supplier\n  SALE // order shipped / confirmed\n  RETURN\n  ADJUSTMENT // manual correction / breakage\n  RESERVE // held for pending order\n  RELEASE // reservation released\n}\n\nenum DiscountType {\n  PERCENT\n  FIXED\n}\n\n// ════════════════════════════════════════════════════════════\n//  USERS & PERMISSIONS (permission-based access, no roles)\n//  Customers and staff are the same table. What a user can do\n//  is decided ONLY by the rows in user_permissions.\n//  Example codes: products.manage, inventory.manage,\n//  orders.view, orders.manage, payments.view, payments.refund,\n//  users.manage, coupons.manage, content.manage, reports.view\n// ════════════════════════════════════════════════════════════\n\nmodel User {\n  id              Int       @id @default(autoincrement())\n  email           String    @unique @db.VarChar(255)\n  phoneNumber     String?   @unique @map(\"phone_number\") @db.VarChar(20)\n  firstName       String    @map(\"first_name\") @db.VarChar(255)\n  lastName        String?   @map(\"last_name\") @db.VarChar(255)\n  password        String    @db.Text\n  profilePicture  String?   @map(\"profile_picture\") @db.VarChar(255)\n  isActive        Boolean   @default(true) @map(\"is_active\")\n  emailVerifiedAt DateTime? @map(\"email_verified_at\")\n  lastLogin       DateTime? @map(\"last_login\")\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n\n  permissions            UserPermission[]        @relation(\"UserPermissions\")\n  grantedPerms           UserPermission[]        @relation(\"PermissionGrantor\")\n  permissionLogs         PermissionLog[]         @relation(\"PermissionLogTarget\")\n  addresses              Address[]\n  refreshTokens          RefreshToken[]\n  cart                   Cart?\n  orders                 Order[]\n  reviews                Review[]\n  wishlist               WishlistItem[]\n  designs                VisualizerDesign[]\n  stockMovements         StockMovement[]\n  orderHistory           OrderStatusHistory[]\n  jobTitle               String?                 @map(\"job_title\") @db.VarChar(100) // public role name, e.g. \"Showroom Manager\"\n  bio                    String?                 @db.VarChar(500)\n  showOnHomepage         Boolean                 @default(false) @map(\"show_on_homepage\")\n  displayOrder           Int                     @default(0) @map(\"display_order\")\n  forgetPasswordRequests ForgetPasswordRequest[]\n  role                   Role[]\n  payments               Payment[]\n  blogPosts              BlogPost[]\n\n  @@index([showOnHomepage, displayOrder])\n  @@map(\"users\")\n}\n\nenum BlogStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nmodel BlogPost {\n  id             Int        @id @default(autoincrement())\n  slug           String     @unique @db.VarChar(200)\n  locale         String     @default(\"en\") @db.VarChar(5)\n  title          String     @db.VarChar(255)\n  excerpt        String?    @db.VarChar(500)\n  content        String     @db.LongText // raw MDX\n  coverImage     String?    @db.Text\n  coverAlt       String?    @db.VarChar(255)\n  tags           String?    @db.VarChar(255) // comma-separated, like Product.colors\n  readingMinutes Int        @default(1)\n  status         BlogStatus @default(DRAFT)\n  featured       Boolean    @default(false)\n  seoTitle       String?    @db.VarChar(255)\n  seoDescription String?    @db.VarChar(500)\n  authorId       Int?\n  publishedAt    DateTime?\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  author User? @relation(fields: [authorId], references: [id], onDelete: SetNull)\n\n  @@index([status, publishedAt])\n  @@index([locale, status, publishedAt])\n  @@map(\"blog_post\")\n}\n\n// Refresh tokens are NEVER stored in plain text: only a SHA-256 hash.\n// Each refresh rotates the token; all tokens from one login share a familyId\n// so reuse of an old token can revoke the whole family.\nmodel RefreshToken {\n  id           Int       @id @default(autoincrement())\n  userId       Int       @map(\"user_id\")\n  tokenHash    String    @unique @map(\"token_hash\") @db.VarChar(64)\n  familyId     String    @map(\"family_id\") @db.VarChar(36)\n  expiresAt    DateTime  @map(\"expires_at\")\n  revokedAt    DateTime? @map(\"revoked_at\")\n  replacedById Int?      @map(\"replaced_by_id\")\n  userAgent    String?   @map(\"user_agent\") @db.VarChar(255)\n  ip           String?   @db.VarChar(45)\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([familyId])\n  @@index([expiresAt])\n  @@map(\"refresh_tokens\")\n}\n\nmodel Permission {\n  id          Int      @id @default(autoincrement())\n  code        String   @unique @db.VarChar(100) // e.g. \"orders.manage\"\n  description String?  @db.VarChar(255)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  users UserPermission[]\n\n  @@map(\"permissions\")\n}\n\nmodel UserPermission {\n  userId       Int      @map(\"user_id\")\n  permissionId Int      @map(\"permission_id\")\n  grantedById  Int?     @map(\"granted_by_id\")\n  grantedAt    DateTime @default(now()) @map(\"granted_at\")\n\n  user       User       @relation(\"UserPermissions\", fields: [userId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n  grantedBy  User?      @relation(\"PermissionGrantor\", fields: [grantedById], references: [id], onDelete: SetNull)\n\n  @@id([userId, permissionId])\n  @@map(\"user_permissions\")\n}\n\nmodel PermissionLog {\n  id             Int      @id @default(autoincrement())\n  targetUserId   Int      @map(\"target_user_id\")\n  actorUserId    Int?     @map(\"actor_user_id\")\n  permissionCode String   @map(\"permission_code\") @db.VarChar(100)\n  action         String   @db.VarChar(20) // GRANTED | REVOKED\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  target User @relation(\"PermissionLogTarget\", fields: [targetUserId], references: [id], onDelete: Cascade)\n\n  @@index([targetUserId])\n  @@map(\"permission_logs\")\n}\n\nmodel Address {\n  id        Int      @id @default(autoincrement())\n  userId    Int      @map(\"user_id\")\n  label     String?  @db.VarChar(50) // Home, Site, Office\n  fullName  String   @map(\"full_name\") @db.VarChar(255)\n  phone     String   @db.VarChar(20)\n  country   String   @default(\"Rwanda\") @db.VarChar(100)\n  province  String?  @db.VarChar(100)\n  district  String   @db.VarChar(100)\n  sector    String?  @db.VarChar(100)\n  street    String   @db.VarChar(255)\n  notes     String?  @db.Text\n  isDefault Boolean  @default(false) @map(\"is_default\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"addresses\")\n}\n\n// ════════════════════════════════════════════════════════════\n//  CATALOG\n// ════════════════════════════════════════════════════════════\n\nmodel Category {\n  id          Int      @id @default(autoincrement())\n  name        String   @db.VarChar(150)\n  slug        String   @unique @db.VarChar(160)\n  description String?  @db.Text\n  image       String?  @db.Text\n  parentId    Int?     @map(\"parent_id\")\n  sortOrder   Int      @default(0) @map(\"sort_order\")\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  parent   Category?  @relation(\"CategoryTree\", fields: [parentId], references: [id], onDelete: SetNull)\n  children Category[] @relation(\"CategoryTree\")\n  products Product[]\n\n  @@map(\"category\")\n}\n\n// A \"product\" is a tile design (e.g. \"Carrara Marble Look\").\n// Each size / finish / shade you can actually buy is a ProductVariant.\nmodel Product {\n  id            Int     @id @default(autoincrement())\n  name          String\n  slug          String? @unique @db.VarChar(200)\n  categoryId    Int?\n  category      String // legacy slug, kept for existing pages\n  categoryLabel String\n  description   String  @db.Text\n  sizes         String // legacy display string, e.g. \"60x60, 30x60\"\n  badge         String?\n  gradient      String  @db.Text\n  image         String  @db.Text\n  colors        String  @db.Text\n  useCase       String // floor | wall | outdoor | bathroom ...\n  collection    String\n\n  // tile specs shared by all variants\n  material        String? @db.VarChar(100) // ceramic, porcelain, ...\n  origin          String? @db.VarChar(100)\n  slipRating      String? @db.VarChar(50) // R9, R10, ...\n  waterAbsorption String? @db.VarChar(50)\n  isRectified     Boolean @default(false)\n\n  status         String   @default(\"ACTIVE\") @db.VarChar(20) // ACTIVE | DRAFT | ARCHIVED\n  featured       Boolean  @default(false)\n  seoTitle       String?  @db.VarChar(255)\n  seoDescription String?  @db.VarChar(500)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  categoryRef Category?        @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  variants    ProductVariant[]\n  images      ProductImage[]\n  reviews     Review[]\n  wishlist    WishlistItem[]\n  collections CollectionItem[]\n  projects    ProjectTile[]\n\n  @@index([categoryId])\n  @@index([status, featured])\n  @@map(\"product\")\n}\n\nmodel ProductImage {\n  id        Int     @id @default(autoincrement())\n  productId Int\n  url       String  @db.Text\n  alt       String? @db.VarChar(255)\n  sortOrder Int     @default(0)\n  isPrimary Boolean @default(false)\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"productimage\")\n}\n\nmodel ProductVariant {\n  id          Int      @id @default(autoincrement())\n  productId   Int\n  sku         String   @unique @db.VarChar(64)\n  size        String   @db.VarChar(50)\n  finish      String?  @db.VarChar(50)\n  color       String?  @db.VarChar(80)\n  thicknessMm Decimal? @db.Decimal(4, 1)\n  shadeCode   String?  @db.VarChar(50)\n\n  pricePerSqm          Decimal  @db.Decimal(12, 2) // 11,500\n  containerPricePerSqm Decimal? @db.Decimal(12, 2) // 11,000, null = not sold by container\n  sqmPerContainer      Decimal? @db.Decimal(10, 2) // m² in one container\n  compareAtPrice       Decimal? @db.Decimal(12, 2) // strike-through price per m²\n  currency             String   @default(\"RWF\") @db.VarChar(3)\n\n  piecesPerBox   Int      @default(1)\n  sqmPerBox      Decimal  @default(1) @db.Decimal(8, 3)\n  pricePerBox    Decimal  @default(0) @db.Decimal(12, 2)\n  weightKgPerBox Decimal? @db.Decimal(8, 2)\n\n  image      String?  @db.Text\n  textureUrl String?  @db.Text\n  active     Boolean  @default(true)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  product        Product                @relation(fields: [productId], references: [id], onDelete: Cascade)\n  inventory      Inventory?\n  stockMovements StockMovement[]\n  cartItems      CartItem[]\n  orderItems     OrderItem[]\n  designItems    VisualizerDesignItem[]\n\n  @@index([productId])\n  @@map(\"productvariant\")\n}\n\nmodel Collection {\n  id          Int              @id @default(autoincrement())\n  name        String           @unique\n  slug        String?          @unique @db.VarChar(160)\n  description String           @db.Text\n  image       String           @db.Text\n  featured    Boolean          @default(false)\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n  items       CollectionItem[]\n\n  @@map(\"collection\")\n}\n\nmodel CollectionItem {\n  id           Int        @id @default(autoincrement())\n  collectionId Int\n  productId    Int\n  collection   Collection @relation(fields: [collectionId], references: [id], onDelete: Cascade)\n  product      Product    @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([collectionId, productId])\n  @@map(\"collectionitem\")\n}\n\n// ════════════════════════════════════════════════════════════\n//  INVENTORY\n// ════════════════════════════════════════════════════════════\n\nmodel Inventory {\n  id             Int      @id @default(autoincrement())\n  variantId      Int      @unique\n  onHandSqm      Decimal  @map(\"onHandBoxes\") // m² in stock                @default(0) @db.Decimal(12, 2)\n  reservedSqm    Decimal  @map(\"reservedBoxes\") // m² held by unpaid orders @default(0) @db.Decimal(12, 2)\n  reorderLevel   Decimal  @default(0) @db.Decimal(12, 2) // m²\n  allowBackorder Boolean  @default(false)\n  updatedAt      DateTime @updatedAt\n\n  variant ProductVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n\n  @@map(\"inventory\")\n}\n\n// Append-only ledger: every stock change gets a row.\nmodel StockMovement {\n  id          Int               @id @default(autoincrement())\n  variantId   Int\n  type        StockMovementType\n  quantity    Decimal           @db.Decimal(12, 2)\n  reference   String?           @db.VarChar(100)\n  note        String?           @db.VarChar(255)\n  createdById Int?\n  createdAt   DateTime          @default(now())\n\n  variant   ProductVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  createdBy User?          @relation(fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([variantId, createdAt])\n  @@map(\"stockmovement\")\n}\n\n// ════════════════════════════════════════════════════════════\n//  CART & WISHLIST\n// ════════════════════════════════════════════════════════════\n\nmodel Cart {\n  id        Int      @id @default(autoincrement())\n  userId    Int?     @unique\n  sessionId String?  @unique @db.VarChar(100) // guest carts\n  couponId  Int?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user   User?      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  coupon Coupon?    @relation(fields: [couponId], references: [id], onDelete: SetNull)\n  items  CartItem[]\n\n  @@map(\"cart\")\n}\n\nmodel CartItem {\n  id        Int      @id @default(autoincrement())\n  cartId    Int\n  variantId Int\n  saleType  SaleType @default(SQM)\n  quantity  Decimal  @default(1) @db.Decimal(10, 2)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  cart    Cart           @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  variant ProductVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n\n  @@unique([cartId, variantId, saleType])\n  @@map(\"cartitem\")\n}\n\nmodel WishlistItem {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  productId Int\n  createdAt DateTime @default(now())\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, productId])\n  @@map(\"wishlistitem\")\n}\n\n// ════════════════════════════════════════════════════════════\n//  ORDERS, PAYMENTS, DELIVERY\n// ════════════════════════════════════════════════════════════\n\nmodel DeliveryZone {\n  id             Int      @id @default(autoincrement())\n  name           String   @db.VarChar(150)\n  districts      String   @db.Text\n  baseFee        Decimal  @db.Decimal(12, 2)\n  feePerSqm      Decimal  @map(\"feePerBox\") // shipping per m², same column as before @default(0) @db.Decimal(12, 2)\n  freeOverAmount Decimal? @db.Decimal(12, 2)\n  estimatedDays  Int      @default(2)\n  active         Boolean  @default(true)\n\n  orders Order[]\n\n  @@map(\"deliveryzone\")\n}\n\nmodel Coupon {\n  id             Int          @id @default(autoincrement())\n  code           String       @unique @db.VarChar(50)\n  description    String?      @db.VarChar(255)\n  type           DiscountType\n  value          Decimal      @db.Decimal(12, 2)\n  minOrderAmount Decimal?     @db.Decimal(12, 2)\n  maxUses        Int?\n  usedCount      Int          @default(0)\n  startsAt       DateTime?\n  expiresAt      DateTime?\n  active         Boolean      @default(true)\n  createdAt      DateTime     @default(now())\n\n  carts  Cart[]\n  orders Order[]\n\n  @@map(\"coupon\")\n}\n\nmodel Order {\n  id          Int     @id @default(autoincrement())\n  orderNumber String  @unique @db.VarChar(30) // \"MC-2026-000123\"\n  userId      Int?\n  guestEmail  String? @db.VarChar(255)\n  guestPhone  String? @db.VarChar(20)\n\n  status        OrderStatus       @default(PENDING)\n  paymentStatus PaymentStatus     @default(PENDING)\n  fulfillment   FulfillmentMethod @default(DELIVERY)\n\n  subtotal      Decimal @db.Decimal(12, 2)\n  discountTotal Decimal @default(0) @db.Decimal(12, 2)\n  shippingFee   Decimal @default(0) @db.Decimal(12, 2)\n  taxTotal      Decimal @default(0) @db.Decimal(12, 2)\n  grandTotal    Decimal @db.Decimal(12, 2)\n  currency      String  @default(\"RWF\") @db.VarChar(3)\n\n  couponId       Int?\n  deliveryZoneId Int?\n  // address snapshot (so later edits don't change old orders)\n  shipFullName   String? @db.VarChar(255)\n  shipPhone      String  @db.VarChar(20)\n  shipProvince   String? @db.VarChar(100)\n  shipDistrict   String? @db.VarChar(100)\n  shipSector     String? @db.VarChar(100)\n  shipStreet     String? @db.VarChar(255)\n  shipNotes      String? @db.Text\n\n  customerNote String?              @db.Text\n  internalNote String?              @db.Text\n  placedAt     DateTime             @default(now())\n  paidAt       DateTime?\n  shippedAt    DateTime?\n  deliveredAt  DateTime?\n  cancelledAt  DateTime?\n  updatedAt    DateTime             @updatedAt\n  user         User?                @relation(fields: [userId], references: [id], onDelete: SetNull)\n  coupon       Coupon?              @relation(fields: [couponId], references: [id], onDelete: SetNull)\n  deliveryZone DeliveryZone?        @relation(fields: [deliveryZoneId], references: [id], onDelete: SetNull)\n  items        OrderItem[]\n  payments     Payment[]\n  history      OrderStatusHistory[]\n  invoices     Invoice[]\n\n  @@index([userId])\n  @@index([status, placedAt])\n  @@map(\"order\")\n}\n\nmodel OrderItem {\n  id          Int      @id @default(autoincrement())\n  orderId     Int\n  variantId   Int?\n  productName String   @db.VarChar(255)\n  sku         String   @db.VarChar(64)\n  size        String   @db.VarChar(50)\n  finish      String?  @db.VarChar(50)\n  shadeCode   String?  @db.VarChar(50)\n  image       String?  @db.Text\n  saleType    SaleType @default(SQM)\n  quantity    Decimal  @db.Decimal(10, 2) // always m²\n  containers  Int? // how many containers, for display\n  sqmPerBox   Decimal? @db.Decimal(8, 3) // legacy, now optional\n  unitPrice   Decimal  @db.Decimal(12, 2) // price per m²\n  lineTotal   Decimal  @db.Decimal(12, 2)\n\n  order   Order           @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  variant ProductVariant? @relation(fields: [variantId], references: [id], onDelete: SetNull)\n\n  @@index([orderId])\n  @@map(\"orderitem\")\n}\n\nenum InvoiceKind {\n  PROFORMA\n  INVOICE\n  CREDIT_NOTE\n}\n\nmodel Invoice {\n  id        Int         @id @default(autoincrement())\n  orderId   Int\n  kind      InvoiceKind\n  number    String      @unique @db.VarChar(40)\n  fileKey   String      @unique @db.VarChar(64)\n  sha256    String      @db.VarChar(64)\n  sizeBytes Int\n  total     Decimal     @db.Decimal(12, 2)\n  currency  String      @default(\"RWF\") @db.VarChar(3)\n  issuedAt  DateTime    @default(now())\n\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  @@unique([orderId, kind])\n  @@index([orderId])\n  @@map(\"invoice\")\n}\n\nmodel OrderStatusHistory {\n  id          Int         @id @default(autoincrement())\n  orderId     Int\n  status      OrderStatus\n  note        String?     @db.VarChar(255)\n  changedById Int?\n  createdAt   DateTime    @default(now())\n\n  order     Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  changedBy User? @relation(fields: [changedById], references: [id], onDelete: SetNull)\n\n  @@index([orderId])\n  @@map(\"orderstatushistory\")\n}\n\nmodel Payment {\n  id             Int           @id @default(autoincrement())\n  orderId        Int\n  method         PaymentMethod\n  status         PaymentStatus @default(PENDING)\n  amount         Decimal       @db.Decimal(12, 2)\n  currency       String        @default(\"RWF\") @db.VarChar(3)\n  provider       String?       @db.VarChar(50) // gateway name (e.g. Flutterwave, Paypack)\n  providerRef    String?       @unique @db.VarChar(150) // gateway transaction id\n  payerPhone     String?       @db.VarChar(20) // mobile money number\n  failureReason  String?       @db.VarChar(255)\n  recordedById   Int?\n  rawResponse    Json?\n  paidAt         DateTime?\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  refundedAmount Decimal       @default(0) @db.Decimal(12, 2)\n  refundedAt     DateTime?\n  refundReason   String?       @db.VarChar(255)\n  note           String?       @db.VarChar(255)\n  proofUrl       String?       @db.Text\n  user           User?         @relation(fields: [recordedById], references: [id], onDelete: SetNull)\n  order          Order         @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([status])\n  @@map(\"payment\")\n}\n\n// ════════════════════════════════════════════════════════════\n//  REVIEWS\n// ════════════════════════════════════════════════════════════\n\nmodel Review {\n  id        Int      @id @default(autoincrement())\n  productId Int\n  userId    Int\n  rating    Int // 1–5\n  title     String?  @db.VarChar(150)\n  body      String?  @db.Text\n  approved  Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([productId, userId])\n  @@map(\"review\")\n}\n\n// ════════════════════════════════════════════════════════════\n//  VISUALIZER (try tiles in a room)\n// ════════════════════════════════════════════════════════════\n\nmodel VisualizerScene {\n  id        Int      @id @default(autoincrement())\n  name      String   @db.VarChar(150) // \"Modern Bathroom\"\n  roomType  String   @db.VarChar(50) // bathroom | kitchen | living | outdoor\n  image     String   @db.Text // base room image\n  thumbnail String?  @db.Text\n  // surfaces the customer can tile: polygons / masks for floor, wall, backsplash...\n  surfaces  Json\n  active    Boolean  @default(true)\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  designs VisualizerDesign[]\n\n  @@map(\"visualizerscene\")\n}\n\nmodel VisualizerDesign {\n  id           Int      @id @default(autoincrement())\n  userId       Int?\n  sessionId    String?  @db.VarChar(100) // guests\n  sceneId      Int?\n  name         String?  @db.VarChar(150)\n  shareToken   String?  @unique @db.VarChar(64) // public share link\n  previewImage String?  @db.Text\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  user  User?                  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  scene VisualizerScene?       @relation(fields: [sceneId], references: [id], onDelete: SetNull)\n  items VisualizerDesignItem[]\n\n  @@index([userId])\n  @@map(\"visualizerdesign\")\n}\n\nmodel ForgetPasswordRequest {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  codeHash  String\n  expiresAt DateTime\n  attempts  Int      @default(0)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\n// One row per surface in the design (floor = variant A, wall = variant B...)\nmodel VisualizerDesignItem {\n  id         Int     @id @default(autoincrement())\n  designId   Int\n  variantId  Int\n  surfaceKey String  @db.VarChar(50) // \"floor\", \"wall\", \"backsplash\"\n  groutColor String? @db.VarChar(20)\n  rotation   Int     @default(0)\n  layout     String? @db.VarChar(30) // straight, brick, herringbone\n\n  design  VisualizerDesign @relation(fields: [designId], references: [id], onDelete: Cascade)\n  variant ProductVariant   @relation(fields: [variantId], references: [id], onDelete: Cascade)\n\n  @@unique([designId, surfaceKey])\n  @@map(\"visualizerdesignitem\")\n}\n\n// ════════════════════════════════════════════════════════════\n//  MARKETING / CONTENT (unchanged from before)\n// ════════════════════════════════════════════════════════════\n\nmodel Project {\n  id          Int           @id @default(autoincrement())\n  title       String\n  type        String\n  description String        @db.Text\n  gradient    String        @db.Text\n  image       String        @db.Text\n  large       Boolean       @default(false)\n  location    String\n  area        String\n  year        String\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n  tiles       ProjectTile[]\n\n  @@map(\"project\")\n}\n\nmodel ProjectTile {\n  id        Int     @id @default(autoincrement())\n  projectId Int\n  productId Int\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, productId])\n  @@map(\"projecttile\")\n}\n\nmodel Testimonial {\n  id        Int      @id @default(autoincrement())\n  text      String   @db.Text\n  name      String\n  role      String\n  initials  String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"testimonial\")\n}\n\nmodel Catalogue {\n  id          Int      @id @default(autoincrement())\n  title       String\n  description String   @db.Text\n  coverImage  String   @db.Text\n  fileUrl     String   @db.Text\n  category    String   @default(\"general\")\n  year        String   @default(\"\")\n  published   Boolean  @default(true)\n  featured    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"catalogue\")\n}\n\nmodel Role {\n  id       Int    @id // fixed IDs, kept in sync with ROLE_IDS in constants.ts\n  roleName String @unique\n  users    User[]\n}\n\nenum ContactStatus {\n  NEW\n  READ\n  REPLIED\n  ARCHIVED\n}\n\nmodel ContactMessage {\n  id          Int           @id @default(autoincrement())\n  firstName   String        @db.VarChar(80)\n  lastName    String        @db.VarChar(80)\n  email       String        @db.VarChar(254)\n  phone       String?       @db.VarChar(20)\n  projectType String?       @db.VarChar(40)\n  message     String        @db.Text\n  status      ContactStatus @default(NEW)\n  ackSentAt   DateTime?\n  replyText   String?       @db.Text\n  repliedAt   DateTime?\n  repliedById Int?\n  ipHash      String?       @db.VarChar(64) // hashed, for rate limiting only\n  createdAt   DateTime      @default(now())\n\n  @@index([status, createdAt])\n  @@index([email, createdAt])\n  @@index([ipHash, createdAt])\n  @@map(\"contact_message\")\n}\n\nmodel MediaFile {\n  id           Int      @id @default(autoincrement())\n  name         String   @db.VarChar(255)\n  originalName String   @map(\"original_name\") @db.VarChar(255)\n  url          String   @unique @db.VarChar(500)\n  kind         String   @db.VarChar(10) // image | file\n  mimeType     String   @map(\"mime_type\") @db.VarChar(100)\n  size         Int\n  alt          String?  @db.VarChar(255)\n  uploadedById Int?     @map(\"uploaded_by_id\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  @@index([kind, createdAt])\n  @@map(\"media_file\")\n}\n"
}

